appearances.css:
.app{display:flex;flex-wrap:wrap;gap:3px 5px;align-items:center;padding:6px;font-size:9px}
.row,.view{display:contents}
.row label,.view label{display:inline-flex;gap:2px;align-items:center;font-size:9px}
select,button,input[type=file]{font-size:9px;padding:2px 4px;border-radius:3px}
input[type=checkbox]{margin:0;width:12px;height:12px}
.line{display:inline-flex;gap:5px;justify-content:flex-start;align-items:center;font-size:9px}
.line>span{white-space:nowrap}
.kn{width:26px!important;height:26px!important;justify-self:center!important}
.kn svg{width:100%;height:100%}
.grid,.proposal,pre,.screen,.status,.mt{flex:1 1 100%;min-width:0}
.grid{display:flex;flex-wrap:wrap;gap:0 2px;padding:4px 4px 3px;background:var(--card-2);border:1px solid var(--line);border-radius:3px}
.control{flex:1 1 44px;min-width:42px;max-width:96px;padding:0;border:0;background:none;display:grid;justify-items:center;align-content:start;gap:0;border-radius:0}
.control .line{display:contents}
.control .kn{order:1}
.control output{order:2;font-size:8px;line-height:1.1;white-space:nowrap}
.control .line>span{order:3;font-size:8px;text-align:center;line-height:1.1;white-space:normal;max-width:100%}
.control .lock{order:4;font-size:8px;display:inline-flex;gap:2px;align-items:center;line-height:1}
.control .lock input{width:12px;height:12px}
.control select{order:1;width:100%;max-width:100%;font-size:8px;padding:3px 0;text-align:center;text-align-last:center;appearance:none;-webkit-appearance:none;cursor:pointer}
.control:has(select) .line>span{order:2}
.control:has(.line>input[type=checkbox]){flex:1 1 60px;max-width:none;grid-auto-flow:column;justify-content:center;align-content:center;gap:4px}
.control:has(.line>input[type=checkbox]) .line>span{order:0;font-size:9px;white-space:normal}
pre{padding:3px 6px;font-size:8.5px;line-height:1.35}
.screen{height:44px}
.status,.proposal{font-size:9px;line-height:1.3}
.proposal{padding:3px 5px}
.mt{gap:1px}
.mr{gap:4px;min-height:10px}
.mr>span{width:44px;font-size:8px}
.control:has(select){flex:1 1 76px;min-width:74px;max-width:none}
.control select{font-size:9px;padding:3px 2px;margin:5px 0 2px}
.control{max-width:none}
.grid{background:none;border:0;padding:0;gap:3px}
.grp{display:flex;flex-wrap:wrap;align-content:flex-start;gap:0 2px;padding:4px 4px 3px;background:var(--card-2);border:1px solid var(--line);border-radius:3px;min-width:0}
.grp[data-g=level]{order:1;flex:4 1 250px}
.grp[data-g=level] .control{flex:1 1 52px}
.grp[data-g=tone]{order:2;flex:3 1 160px}
.grp[data-g=compressor]{order:3;flex:7 1 340px}
.grp[data-g=limiter]{order:4;flex:1 1 70px;align-content:center}
.grp .control{flex:1 1 42px;min-width:40px}
.grp .control:has(select){flex:2 1 72px;min-width:68px}
.grp .control .line>span{letter-spacing:-.04em}
.grp .control{overflow:visible}
.control:has(.line>input[type=checkbox]){grid-auto-flow:column;justify-content:start;align-content:start;gap:5px;flex:1 1 100%;min-width:0;margin:0 0 2px;align-items:center}
.control:has(.line>input[type=checkbox]) .line>input{order:0;width:16px;height:16px;margin:0}
.control:has(.line>input[type=checkbox]) .line>span{order:1;font-size:9px;text-align:left}
.control select{margin:4px 0 2px}
